        if (args.length != 2) {
            System.err.println("Usage: AnimationSamplerLauncher <config_path> <output_path>");
            System.exit(1);
        }

        Thread.setDefaultUncaughtExceptionHandler((thread, throwable) -> {
            throwable.printStackTrace(System.err);
            System.exit(1);
